function onEdit(e) {
  try {
    const sheet = e.range.getSheet();
    if (sheet.getName() !== 'Proposals') return;
    if (e.range.getColumn() !== 6) return; // status oszlop
    if (e.value !== 'won') return;

    const row = sheet.getRange(e.range.getRow(), 1, 1, 7).getValues()[0];
    const clients = e.source.getSheetByName('Clients');
    const today = new Date();

    // start_date | name | email | package | price | payment_status | notes
    clients.appendRow([today, row[1], row[2], row[3], row[4], 'pending', '']);
    Logger.log('Új ügyfél áthelyezve: ' + row[1]);
  } catch (err) {
    Logger.log('Hiba: ' + err.message);
  }
}
